"""Apply preregistered inequalities without retuning; compact actual evidence report."""
from phase319_common import *
import statistics
def val(r,k):return None if r[k]=='NA' else float(r[k])
def fmt(x):return 'NA' if x is None else f'{x:.4f}'
def main():
 guard();assert load(ROOT/'INDEPENDENT_QA.json')['status']=='passed';rows=read(ROOT/'PRECISION_COVERAGE.csv');lookup={(r['pool'],r['level'],r['unit'],r['selector']):r for r in rows};decisions=[];macro=[]
 for pool in POOLS:
  get=lambda s:lookup[pool,'pool','POOLED',s]
  base=get('eligible_A_Sh');orig=get('original_A_Sh');sun=get('G_sun');conf=get('G_conf');rev=get('G_reverse');qualified=int(base['selected'])/int(orig['selected']);refchecks={s:val(get(s),'reference_coverage_pct') for s in ['original_A_Sh','eligible_A_Sh','G_sun','G_conf','G_reverse']};knowncoverage=[x for x in refchecks.values() if x is not None];reference_ready=all(x>=95 for x in knowncoverage)
  scenes=[r for r in rows if r['pool']==pool and r['level']=='scene' and r['selector']=='G_sun'];deltas=[val(r,'gain_original_pp') for r in scenes if val(r,'gain_original_pp') is not None];n100=sum(int(r['reference_valid'])>=100 for r in scenes);positive=sum(x>0 for x in deltas);negative=sum(x<0 for x in deltas);zero=sum(x==0 for x in deltas);median=statistics.median(deltas) if deltas else None
  ge=lambda x,t:x is not None and x>=t
  tests=dict(input_90pct=qualified>=.9,reference_95pct=reference_ready,precision_90pct=ge(val(sun,'Shadow_precision_pct'),90),gain_original_5pp=ge(val(sun,'gain_original_pp'),5),retain_30pct=ge(val(sun,'retained_full_A_Sh_pct'),30),five_scenes_100valid=n100>=5,scene_median_positive=median is not None and median>0,scene_majority_positive=bool(deltas) and positive>len(deltas)/2,beat_conf_2pp=ge(val(sun,'gain_conf_pp'),2),beat_reverse_2pp=ge(val(sun,'gain_reverse_pp'),2))
  decision='not_testable' if not tests['input_90pct'] or not tests['reference_95pct'] else 'go_to_method_design' if all(tests.values()) else 'no_go'
  decisions.append(dict(pool=pool,original_A_Sh=int(orig['selected']),qualified_A_Sh=int(base['selected']),qualified_A_Sh_pct=100*qualified,reference_coverage_pct=refchecks,sun_selected=int(sun['selected']),sun_precision_pct=val(sun,'Shadow_precision_pct'),original_eligible_precision_pct=val(base,'Shadow_precision_pct'),gain_original_pp=val(sun,'gain_original_pp'),retained_full_A_Sh_pct=val(sun,'retained_full_A_Sh_pct'),conf_precision_pct=val(conf,'Shadow_precision_pct'),gain_conf_pp=val(sun,'gain_conf_pp'),reverse_selected=int(rev['selected']),reverse_retained_pct=val(rev,'retained_full_A_Sh_pct'),reverse_precision_pct=val(rev,'Shadow_precision_pct'),gain_reverse_pp=val(sun,'gain_reverse_pp'),scenes_at_least100_valid=n100,comparable_scenes=len(deltas),median_scene_gain_pp=median,positive_scenes=positive,negative_scenes=negative,zero_scenes=zero,criteria=tests,decision=decision))
  for selector in ['original_A_Sh','eligible_A_Sh','G_sun','G_conf','G_reverse','unmatched_observed','unmatched_unknown']:
   vv=[val(r,'Shadow_precision_pct') for r in rows if r['pool']==pool and r['level']=='scene' and r['selector']==selector and val(r,'Shadow_precision_pct') is not None];macro.append(dict(pool=pool,selector=selector,scenes_with_valid_support=len(vv),scene_macro_precision_pct=statistics.mean(vv) if vv else None,scene_median_precision_pct=statistics.median(vv) if vv else None,pooled_precision_pct=val(get(selector),'Shadow_precision_pct')))
 table(ROOT/'GO_NO_GO.csv',decisions);table(ROOT/'SCENE_SUMMARY.csv',macro)
 globaldecision='go_to_method_design' if all(d['decision']=='go_to_method_design' for d in decisions) else 'not_testable' if any(d['decision']=='not_testable' for d in decisions) else 'no_go'
 write(ROOT/'DECISION.json',dict(decision=globaldecision,pools=decisions,both_pools_required=True,thresholds_not_changed=True))
 text=['# Phase319：太阳方向筛查','',f'结论：**{globaldecision}**。固定160图均已列入元数据表；两池的实际几何输入覆盖、精度和保留量如下。此为历史已暴露数据上的固定规则探索，未训练、拟合或新增神经前向。','', '| 池 | 几何输入覆盖A_Sh% | 选中/原A_Sh | precision% | 相对原集pp | 保留% | 同数量高分% | 反方向% | 判定 |','|---|---:|---:|---:|---:|---:|---:|---:|---|']
 for d in decisions:text.append(f"|{d['pool']}|{fmt(d['qualified_A_Sh_pct'])}|{d['sun_selected']}/{d['original_A_Sh']}|{fmt(d['sun_precision_pct'])}|{fmt(d['gain_original_pp'])}|{fmt(d['retained_full_A_Sh_pct'])}|{fmt(d['conf_precision_pct'])}|{fmt(d['reverse_precision_pct'])}|{d['decision']}|")
 text+=['','太阳角来自实际同scene MTL。原TIFF的CRS/affine与1000→512（SPARCS）或原512裁剪（L8）组合；地理正反投影和九点方向/尺度误差有独立核验。L8仅用原轴/原编码恒等核对100图，rawfill0从精度分母排除，仍计完整影像保留率分母。','', '高度200–12000m、角容差±5°、半像元对角线径向容差均事前固定。从候选Shadow朝太阳找Source预测Cloud；反方向为固定安慰剂。G_conf每图同k，原q_Shadow降序、row-major破并列。所有选择及核先封存，独立CPU进程随后读取参考；FFT计数经整数误差与固定无标签直接偏移抽验。','']
 for d in decisions:
  failed=[k for k,v in d['criteria'].items() if not v]
  text.append(f"{d['pool']}：未过条件 {', '.join(failed) if failed else '无'}；>=100有效选中像元的scene {d['scenes_at_least100_valid']}；可比较scene {d['comparable_scenes']}，中位增量 {fmt(d['median_scene_gain_pp'])}pp，正/负/零 {d['positive_scenes']}/{d['negative_scenes']}/{d['zero_scenes']}。反方向选中 {d['reverse_selected']}，保留 {fmt(d['reverse_retained_pct'])}%。参考覆盖见GO_NO_GO原始字段，零支持记NA。")
 text+=['','完整逐图/scene/池计数、参考排除及coverage见PRECISION_COVERAGE.csv；原native子类见NATIVE_STRATA.csv（biome不是像元类别）；上下文完整性、supported但外部未知、unmatched_observed和unmatched_unknown分别保留。后者不能作负标签，Source漏云同样可能造成失配。同一Source产生Cloud和Shadow，支持不等于真实云影配对；平面/scene中心太阳角忽略地形、视角与云体视差。','', '保留率使用原完整A_Sh，precision使用共同定义的有效参考；同k不保证参考有效数相同。按scene汇总，不把patch或像元当独立重复，不做像元bootstrap。此简化筛选不是完整Fmask复现，也不构成新方法或泛化证明。','', '原14天窗口逐字继承，不重置。未满足全部两池门槛则停止当前候选，不改高度/角度/阈值、不自动进入下一phase。所有参数、选择数、失败与资源证据保留；完整备份及哈希验收完成后才交付。']
 (ROOT/'RESULT.md').write_text('\n'.join(text)+'\n',encoding='utf-8')
 write(ROOT/'CANDIDATE_LEDGER.json',dict(prior=[dict(candidate='CB',phase=317,outcome='historical failures/cost retained in original reports; unchanged'),dict(candidate='Flip-CB',phase=318,outcome='no consistent two-pool unique reliability gain; closed; original reports unchanged')],current=dict(phase=319,candidate='fixed sun-direction geometry',geometry_attempts=1,trainings=0,neural_forwards=0,controls=['same-k original confidence','fixed reverse sun direction'],decision=globaldecision),original_window_sha256=sha(ROOT/'DECISION_WINDOW.json'),no_automatic_next_phase=True))
 print('Phase319 actual preregistered decision:',globaldecision,flush=True)
if __name__=='__main__':main()
